// Starter module. Replace it with your own code.

export function name() {
  return 'example-app';
}

// Smoke test, so a new project's test command has something to run. Node's own
// runner discovers every file under `test/`, and there is no `.test.` in the
// name, so a vitest added later collects its own files and not this one too.
import assert from 'node:assert/strict';
import test from 'node:test';

import { name } from '../src/index.js';

await test('the starter module loads', () => {
  assert.equal(name(), 'example-app');
});

// Smoke test for the runner this project installed, so `npm test` has
// something to collect. `node --test` never sees it: a `tests/` directory and
// a `.spec.` name are vitest discovery, not node's, so the two runners each
// have one file of their own and neither reads the other's.
import { expect, test } from 'vitest';

import { name } from '../src/index.js';

test('the starter module loads', () => {
  expect(name()).toBe('example-app');
});

